export type Pin = { name: string; lat: number; lon: number; label?: boolean };

/** Where Vikkaa works. `label` marks the towns named on the map (kept to a few so mobile stays clean). */
export const PINS: readonly Pin[] = [
  { name: 'Colombo', lat: 6.9271, lon: 79.8612, label: true },
  { name: 'Negombo', lat: 7.2083, lon: 79.8358, label: true },
  { name: 'Gampaha', lat: 7.0873, lon: 80.0144, label: true },
  { name: 'Kelaniya', lat: 6.9553, lon: 79.922 },
  { name: 'Battaramulla', lat: 6.8986, lon: 79.9223 },
  { name: 'Mount Lavinia', lat: 6.839, lon: 79.8653 },
  { name: 'Panadura', lat: 6.7132, lon: 79.9026 },
  { name: 'Kalutara', lat: 6.5854, lon: 79.9607, label: true },
];

/** Map projection centre. x grows east, y grows north, 1 unit = 1° of latitude. */
const LAT0 = 7.85;
const LON0 = 80.78;
const COS0 = Math.cos((LAT0 * Math.PI) / 180);
export const project = (lon: number, lat: number) => [(lon - LON0) * COS0, lat - LAT0] as const;

type Ring = readonly (readonly [number, number])[];

function inRing(lon: number, lat: number, ring: Ring) {
  let hit = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const [xi, yi] = ring[i];
    const [xj, yj] = ring[j];
    if (yi > lat !== yj > lat && lon < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) hit = !hit;
  }
  return hit;
}
const inside = (lon: number, lat: number) => LANKA.some((ring) => inRing(lon, lat, ring));

/** A hand-traced approximation of the Western Province's inland boundary (Gampaha, Colombo, Kalutara); the sea closes it. */
const WESTERN: Ring = [
  [79.5, 7.32], [79.95, 7.33], [80.1, 7.28], [80.2, 7.17], [80.22, 7.04], [80.19, 6.95], [80.26, 6.86],
  [80.31, 6.74], [80.35, 6.6], [80.3, 6.5], [80.15, 6.42], [80.0, 6.39], [79.5, 6.39],
];
export const isWestern = (lon: number, lat: number) => inRing(lon, lat, WESTERN);

/** Relief for the 3D dots: a soft rise for the hill country around Pidurutalagala. */
export const relief = (lon: number, lat: number) => 0.32 * Math.exp(-((lon - 80.75) ** 2 + (lat - 7.0) ** 2) / 0.22);

/** A regular dot grid clipped to the coastline: [x, y, western, lon, lat] per dot, in `project` units. */
export function dots(step: number) {
  const out: [number, number, boolean, number, number][] = [];
  for (let lat = 5.9; lat < 9.9; lat += step)
    for (let lon = 79.65; lon < 81.92; lon += step / COS0)
      if (inside(lon, lat)) {
        const [x, y] = project(lon, lat);
        out.push([x, y, isWestern(lon, lat), lon, lat]);
      }
  return out;
}
